-- POST-INSTALL VERIFICATION for docs/admin-dashboard/COMBINED-BILLING-IDENTITY.PROPOSAL.sql
-- Read-only. Safe to run immediately after install and again during incident review.
-- Prints catalog metadata and aggregate counts only; never subscriber identities.
select jsonb_pretty(jsonb_build_object(
  'writer_12arg_present', to_regprocedure('public.admin_apply_subscription_change(uuid,text,text,integer,timestamptz,uuid,text,timestamptz,boolean,integer,boolean,numeric)') is not null,
  'writer_11arg_dropped', to_regprocedure('public.admin_apply_subscription_change(uuid,text,text,integer,timestamptz,uuid,text,timestamptz,boolean,integer,boolean)') is null,
  'writer_md5', (select md5(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure('public.admin_apply_subscription_change(uuid,text,text,integer,timestamptz,uuid,text,timestamptz,boolean,integer,boolean,numeric)')),
  'writer_expected_md5', '7b4b54f8a55d52578efd75a6aeeb0de0',
  'writer_owner', (select pg_get_userbyid(proowner) from pg_catalog.pg_proc where oid=to_regprocedure('public.admin_apply_subscription_change(uuid,text,text,integer,timestamptz,uuid,text,timestamptz,boolean,integer,boolean,numeric)')),
  'writer_security_definer', (select prosecdef from pg_catalog.pg_proc where oid=to_regprocedure('public.admin_apply_subscription_change(uuid,text,text,integer,timestamptz,uuid,text,timestamptz,boolean,integer,boolean,numeric)')),
  'writer_volatility', (select provolatile from pg_catalog.pg_proc where oid=to_regprocedure('public.admin_apply_subscription_change(uuid,text,text,integer,timestamptz,uuid,text,timestamptz,boolean,integer,boolean,numeric)')),
  'writer_config', (select proconfig from pg_catalog.pg_proc where oid=to_regprocedure('public.admin_apply_subscription_change(uuid,text,text,integer,timestamptz,uuid,text,timestamptz,boolean,integer,boolean,numeric)')),
  'writer_acl', (select proacl::text from pg_catalog.pg_proc where oid=to_regprocedure('public.admin_apply_subscription_change(uuid,text,text,integer,timestamptz,uuid,text,timestamptz,boolean,integer,boolean,numeric)')),
  'reporting_md5', (select md5(prosrc) from pg_catalog.pg_proc where oid=to_regprocedure('public.admin_read_subscriptions(text,jsonb,integer)')),
  'reporting_expected_md5', '7c48e4669969147e110ca4381025b129',
  'reporting_owner', (select pg_get_userbyid(proowner) from pg_catalog.pg_proc where oid=to_regprocedure('public.admin_read_subscriptions(text,jsonb,integer)')),
  'reporting_security_definer', (select prosecdef from pg_catalog.pg_proc where oid=to_regprocedure('public.admin_read_subscriptions(text,jsonb,integer)')),
  'reporting_volatility', (select provolatile from pg_catalog.pg_proc where oid=to_regprocedure('public.admin_read_subscriptions(text,jsonb,integer)')),
  'reporting_config', (select proconfig from pg_catalog.pg_proc where oid=to_regprocedure('public.admin_read_subscriptions(text,jsonb,integer)')),
  'reporting_acl', (select proacl::text from pg_catalog.pg_proc where oid=to_regprocedure('public.admin_read_subscriptions(text,jsonb,integer)')),
  'amount_php_type', (select data_type from information_schema.columns where table_schema='public' and table_name='subscription_history' and column_name='amount_php'),
  'amount_php_precision', (select numeric_precision from information_schema.columns where table_schema='public' and table_name='subscription_history' and column_name='amount_php'),
  'amount_php_scale', (select numeric_scale from information_schema.columns where table_schema='public' and table_name='subscription_history' and column_name='amount_php'),
  'billing_status_check', (select pg_get_constraintdef(c.oid) from pg_catalog.pg_constraint c where c.conrelid='public.subscription_history'::regclass and c.conname='subscription_history_billing_status_check'),
  'billing_snapshot_check', (select pg_get_constraintdef(c.oid) from pg_catalog.pg_constraint c where c.conrelid='public.subscription_history'::regclass and c.conname='subscription_history_billing_snapshot_check'),
  'amount_check', (select pg_get_constraintdef(c.oid) from pg_catalog.pg_constraint c where c.conrelid='public.subscription_history'::regclass and c.conname='subscription_history_amount_php_check'),
  'plan_months_check', (select pg_get_constraintdef(c.oid) from pg_catalog.pg_constraint c where c.conrelid='public.subscription_history'::regclass and c.conname='subscription_history_plan_months_check'),
  'history_rls', (select relrowsecurity from pg_catalog.pg_class where oid='public.subscription_history'::regclass),
  'profiles_username_present', exists (select 1 from pg_catalog.pg_attribute where attrelid='public.profiles'::regclass and attname='username' and not attisdropped),
  'history_indexes', (select jsonb_agg(jsonb_build_object('name',indexname,'def',indexdef) order by indexname) from pg_indexes where schemaname='public' and tablename='subscription_history'),
  'history_rows', (select count(*) from public.subscription_history),
  'profile_rows', (select count(*) from public.profiles),
  'non_null_amounts', (select count(*) from public.subscription_history where amount_php is not null),
  'admin_confirmed_rows', (select count(*) from public.subscription_history where billing_status='admin_confirmed'),
  'paid_rows', (select count(*) from public.subscription_history where billing_status='paid'),
  'complimentary_rows', (select count(*) from public.subscription_history where billing_status='complimentary'),
  'unknown_rows', (select count(*) from public.subscription_history where billing_status='unknown'),
  'null_status_rows', (select count(*) from public.subscription_history where billing_status is null)
)) as post_install_verify;
